mapper.sql:
WHERE item.is_deleted = FALSE
AND ( LOWER(item.name) LIKE CONCAT('%', LOWER(#{filter.query}), '%') OR LOWER(item.item_code) LIKE CONCAT('%', LOWER(#{filter.query}), '%') OR LOWER(COALESCE(item.description, '')) LIKE CONCAT('%', LOWER(#{filter.query}), '%') )
AND item.category_code = #{filter.categoryCode}
AND item.is_active = #{filter.active}
AND item.reorder_point IS NOT NULL AND COALESCE(stock.total_quantity_on_hand, 0) < item.reorder_point
AND ( item.reorder_point IS NULL OR COALESCE(stock.total_quantity_on_hand, 0) >= item.reorder_point )
